#!/usr/bin/env python3
"""Cost-only full-matrix admission, preserving both new and inherited envelopes."""
import os
os.environ.setdefault('OMP_NUM_THREADS','1');os.environ.setdefault('OPENBLAS_NUM_THREADS','1')
import sys,time,json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
import numpy as np
from scripts.structured_common import ROOT,RUN,PUB,CFG,read,write,sha,sequences,verify_freeze
from echo_routing.temporal.structured_inputs import windows
from echo_routing.temporal.structured_budget import workload,caps_fit
from echo_routing.temporal.dense_readout import SequenceReadout

def main(mode):
    freeze=verify_freeze('forecast_freeze.json');cfg=read(CFG);b=cfg['budget'];check=read(PUB/'checks.json');assert check['passed'];manifest=read(PUB/'input_manifest.json');roles={k:dict(v) for k,v in manifest['roles'].items()};fit=sequences('fit');totals=[]
    for role in ['stress_selection','stress_calibration']:roles[role]['a08_stride5_windows']=sum(len(windows(len(q['refs']),5)['centre']) for q in sequences(role))
    for seed in cfg['training']['seeds']:
        pin=manifest['plans'][str(seed)];assert sha(ROOT/pin['path'])==pin['sha256'];plan=np.load(ROOT/pin['path']);assert plan.shape==(6000,2);totals.append(sum(len(fit[int(i)]['refs']) for row in plan for i in row))
    work=workload(roles,totals);physical=[json.loads(s) for s in (RUN/'processes.jsonl').read_text().splitlines()];spent_gpu=sum(x['full_process_wall_seconds'] for x in physical if x['GPU_job'])/3600;spent_cpu=sum(x['process_CPU_seconds'] for x in physical)/3600
    path=RUN/'engineering/FIT_posteriors.private.npy';assert sha(path)==check['FIT_engineering_probability_sha256'];values=np.load(path,allow_pickle=True).item();probe=RUN/'forecast_io_probe';probe.mkdir(exist_ok=True);write_times=[];write_bytes=[]
    for source,arrays in values.items():
        keys=sorted(arrays,key=int);cache=SequenceReadout(probe/source,check['FIT_engineering_probability_sha256']+'|'+source,len(keys),lengths=[len(arrays[k]) for k in keys])
        for i in range(cache.cursor,len(keys)):
            start=time.time();cache.run_one(i,lambda i=i:arrays[keys[i]]);write_times.append(time.time()-start);write_bytes.append(cache.file(i).stat().st_size)
    if not write_times:
        prior=read(PUB/('cache_admission.json' if mode=='formal' else 'cache_admission.json'));io_s=prior['cache_IO_probe']['max_seconds_per_sequence']
    else:io_s=max(write_times)
    completed_dense=completed_jepa=completed_writes=0
    if mode=='formal':
        cached=read(PUB/'cache_fit_manifest.json');assert cached['passed'] and all(r['complete'] for r in cached['records']);completed_dense=sum(roles[k]['a08_stride2_windows'] for k in ['fit','inner_cal']);completed_jepa=roles['fit']['jepa_chunks'];completed_writes=sum(r['committed_sequences'] for r in cached['records'])
    else:assert mode=='cache'
    a08_s=max(r['seconds_per_unit'] for r in check['source_costs']['a08']);jepa_s=max(r['seconds_per_unit'] for r in check['source_costs']['jepa']);remaining_dense=work['a08_dense_windows']-completed_dense;remaining_jepa=work['new_JEPA_chunks']-completed_jepa;remaining_writes=work['source_cache_sequence_writes']-completed_writes;gpu_forward=(remaining_dense+work['a08_original_stress_windows'])*a08_s+remaining_jepa*jepa_s;cache_gpu_seconds=1.5*(gpu_forward+remaining_writes*io_s)+600
    cpu_rate=max(r['per_valid_position_seconds'] for r in check['head_complete_sequence_timing']['cpu'].values());cuda_rate=max(r['per_valid_position_seconds'] for r in check['head_complete_sequence_timing']['cuda'].values());backend='cpu' if cpu_rate<=cuda_rate else 'cuda';train_seconds=work['head_training_valid_positions']*(cpu_rate if backend=='cpu' else cuda_rate)*1.5
    map_rate=max(r['MAP_per_position_seconds'] for r in check['head_complete_sequence_timing']['cpu'].values());map_seconds=1.5*map_rate*(work['inner_MAP_positions']+work['main_MAP_positions']+work['stress_MAP_positions']);atomic_s=max(r['atomic_save_plus_two_updates_seconds'] for r in check['real_FIT_graph_repeat_resume']);checkpoint_seconds=(480+24)*atomic_s;report_CPU_seconds=2*3600;closure_CPU_seconds=.5*3600;source_CPU_seconds=cache_gpu_seconds*1.1
    future_gpu_seconds=cache_gpu_seconds+(train_seconds if backend=='cuda' else 0);future_cpu_seconds=source_CPU_seconds+train_seconds+map_seconds+checkpoint_seconds+report_CPU_seconds+closure_CPU_seconds;new_gpu=spent_gpu+future_gpu_seconds/3600+b['closure_GPUreserve_h'];new_cpu=spent_cpu+future_cpu_seconds/3600+.25
    decoded_sequences=work['inner_sequence_decodes']+work['main_sequence_decodes']+work['stress_sequence_decodes'];cache_seqs=work['source_cache_sequence_writes'];positions=sum(v['positions'] for v in roles.values());current_paths=[RUN,PUB];current_apparent=sum(int(r.split()[0]) for r in subprocess.check_output(['du','-sb',*map(str,current_paths)],text=True).splitlines());current_allocated=sum(int(r.split()[0]) for r in subprocess.check_output(['du','-sB1',*map(str,current_paths)],text=True).splitlines());atomic=max(r['atomic_checkpoint_bytes'] for r in check['real_FIT_graph_repeat_resume']);storage={'current_retained_task_paths_max_apparent_allocated':max(current_apparent,current_allocated),'two_producer_probability_arrays':positions*5*4*2,'original_stress_probability_arrays':sum(roles[k]['positions'] for k in ['stress_selection','stress_calibration'])*5*4,'source_cache_filesystem_and_journals':cache_seqs*(8192+512),'all_decode_filesystem_and_journals':decoded_sequences*(8192+512),'all_decoded_labels_upper':(work['inner_MAP_positions']+work['main_MAP_positions']+work['stress_MAP_positions'])*8,'formal_48000_physical_update_logs':48000*2048,'all8latest_plus24immutable_heads':(8+24)*atomic,'one_atomic_checkpoint_coexistence':atomic,'report_code_and_small_unmetered_artifacts':100_000_000,'IO_probe_and_scratch':20_000_000};peak=sum(storage.values());now=time.time();wall_remaining_upper=(future_gpu_seconds+future_cpu_seconds)/3600+b['closure_GPUreserve_h'];end=now+wall_remaining_upper*3600;passed=caps_fit(b,new_gpu,new_cpu,peak,end)
    result={'all_caps_fit':passed,'stage':mode,'forecast_freeze_git':freeze['git_commit'],'epoch':now,'training_backend':backend,'backend_choice_reason':'measuredcompleteNLLbackwardoptimizercost_only_before_formaloutcomes','formal_updates_at_cache_admission':0,'formal_models':8,'updates_each':6000,'workload':work,'exact_plan_position_totals':totals,'remaining_A08_dense_windows':remaining_dense,'original_A08_stride5_stress_windows':work['a08_original_stress_windows'],'remaining_new_JEPA_chunks':remaining_jepa,'reused_JEPA_inner_and_original_outer_no_new_forward':True,'source_worst_observed_seconds_per_unit':{'a08':a08_s,'jepa':jepa_s},'cache_IO_probe':{'max_seconds_per_sequence':io_s,'observed_probe_writes':len(write_times),'max_npz_bytes':max(write_bytes) if write_bytes else None},'cache_GPU_seconds_upper':cache_gpu_seconds,'head_training_seconds_upper':train_seconds,'head_MAP_seconds_upper':map_seconds,'atomic_checkpoint_seconds_upper':checkpoint_seconds,'report_5000bootstrap_and_metrics_CPU_seconds_allowance':report_CPU_seconds,'closure_CPU_seconds_allowance':closure_CPU_seconds,'spent_new_GPU_hours':spent_gpu,'spent_new_summed_measured_CPU_hours':spent_cpu,'forecast_new_GPU_hours_including2hreserve':new_gpu,'forecast_cumulative_GPU_hours_includingreserve':b['prior_GPUjob_h']+new_gpu,'forecast_new_CPU_hours_including_completed_setup_allowance':new_cpu,'forecast_cumulative_CPU_receipt_hours_plus_allowances':b['prior_summed_measured_CPUreceipt_h']+b['prior_setup_budget_allowance_h']+new_cpu,'storage_components_bytes':storage,'forecast_new_tracked_peak_upper_bytes':peak,'forecast_cumulative_tracked_peak_upper_bytes':b['prior_tracked_storage_upper_bytes']+peak,'remaining_wall_upper_hours':wall_remaining_upper,'forecast_end_epoch':end,'earlier_deadline_epoch':min(b['new_deadline'],b['cumulative_deadline']),'GPU_reserve_is_not_actual_spent_cost':True,'all_prior_charges_and_CPU_provenance_uncertainty_retained':True,'source_full_context_checks_passed':True,'score_or_performance_used_for_cost_tier':False};write(PUB/('cache_admission.json' if mode=='cache' else 'admission.json'),result);print(json.dumps({k:result[k] for k in ['all_caps_fit','training_backend','forecast_new_GPU_hours_including2hreserve','forecast_cumulative_GPU_hours_includingreserve','forecast_new_CPU_hours_including_completed_setup_allowance','forecast_new_tracked_peak_upper_bytes','forecast_end_epoch']}),flush=True);assert passed
if __name__=='__main__':main(sys.argv[1])
